#!/usr/bin/env python3
"""
gpstrackerNODE — ROS2 Jazzy version
Wraps LocalisationSystem and publishes on /automobile/localisation.
"""

import threading
import time
from multiprocessing import Pipe

import rclpy
from rclpy.node import Node
from utils.msg import Localisation  # was: localisation (ROS2 uses CamelCase)

# LocalisationSystem is a project-local module — path unchanged
from locsys import LocalisationSystem


class GpsTrackerNode(Node):
    def __init__(self):
        super().__init__('gpstrackerNODE')

        beacon          = 12345
        id_             = 88
        serverpublickey = '/home/pi/dei_ws/src/input/src/gpstracker/publickey_server.pem'

        self._gpsStR, gpsStS = Pipe(duplex=False)
        self._loc_sys = LocalisationSystem(id_, beacon, serverpublickey, gpsStS)

        self._pub = self.create_publisher(Localisation, '/automobile/localisation', 1)

        self._loc_sys.start()

        # Give the localisation system time to connect
        time.sleep(5)

        self._thread = threading.Thread(target=self._getting, daemon=True)
        self._thread.start()
        self.get_logger().info("gpstrackerNODE started")

    def _getting(self):
        while rclpy.ok():
            try:
                coora = self._gpsStR.recv()
                loc = Localisation()
                loc.timestamp = coora['timestamp']
                loc.pos_a     = coora['coor'][0].real
                loc.pos_b     = coora['coor'][0].imag
                loc.rot_a     = coora['coor'][1].real
                loc.rot_b     = coora['coor'][1].imag
                self._pub.publish(loc)
            except Exception as e:
                self.get_logger().error(f"GPS receive error: {e}")

    def destroy_node(self):
        self._loc_sys.stop()
        self._loc_sys.join()
        super().destroy_node()


def main(args=None):
    rclpy.init(args=args)
    node = GpsTrackerNode()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
